import{_ as a,a as o,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第一册：英语初阶 · 全册易错点 · 第80–105课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第一册：英语初阶 · 全册易错点 · 第80–105课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-1/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第54–79课","link":"/life/english/new-concept/book-1/mistakes-part-03"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第106–131课","link":"/life/english/new-concept/book-1/mistakes-part-05"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册易错点 · 第54–79课","link":"/life/english/new-concept/book-1/mistakes-part-03"},"next":{"text":"第一册：英语初阶 · 全册易错点 · 第106–131课","link":"/life/english/new-concept/book-1/mistakes-part-05"}},"headers":[],"relativePath":"life/english/new-concept/book-1/mistakes-part-04.md","filePath":"life/english/new-concept/book-1/mistakes-part-04.md"}'),l={name:"life/english/new-concept/book-1/mistakes-part-04.md"};function r(s,e,i,h,p,c){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-全册易错点-·-第80–105课" tabindex="-1">第一册：英语初阶 · 全册易错点 · 第80–105课 <a class="header-anchor" href="#第一册-英语初阶-·-全册易错点-·-第80–105课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册易错点 · 第80–105课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="l80-·-need-与-must" tabindex="-1">L80 · need 与 must <a class="header-anchor" href="#l80-·-need-与-must" aria-label="Permalink to &quot;L80 · need 与 must {#l80-·-need-与-must}&quot;">​</a></h2><p>need to go 与 must go 的结构不同；不要写 must to go。</p><p><strong>对照例句：</strong> She must go to the pharmacy before six.</p><p>She 为主语，must 后直接接 go；to the pharmacy 表目的地，before six 表时间界限。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-080">回看讲解和练习</a></p><h2 id="l81-·-have-had-的活动用法" tabindex="-1">L81 · have/had 的活动用法 <a class="header-anchor" href="#l81-·-have-had-的活动用法" aria-label="Permalink to &quot;L81 · have/had 的活动用法 {#l81-·-have-had-的活动用法}&quot;">​</a></h2><p>did 后用 have，而不是 had；have a rest 中 rest 为可数用法。</p><p><strong>对照例句：</strong> We had vegetable soup for lunch.</p><p>Had 是 have 的过去式，此处表示吃喝；vegetable soup 为食物对象，for lunch 表午餐所用。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-081">回看讲解和练习</a></p><h2 id="l82-·-have-had-的活动用法" tabindex="-1">L82 · have/had 的活动用法 <a class="header-anchor" href="#l82-·-have-had-的活动用法" aria-label="Permalink to &quot;L82 · have/had 的活动用法 {#l82-·-have-had-的活动用法}&quot;">​</a></h2><p>did 后用 have，而不是 had；have a rest 中 rest 为可数用法。</p><p><strong>对照例句：</strong> Did you have a good rest after the journey?</p><p>Did 构成过去问句，have 恢复原形；a good rest 表一次充分休息，after the journey 表先后关系。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-082">回看讲解和练习</a></p><h2 id="l83-·-现在完成时入门" tabindex="-1">L83 · 现在完成时入门 <a class="header-anchor" href="#l83-·-现在完成时入门" aria-label="Permalink to &quot;L83 · 现在完成时入门 {#l83-·-现在完成时入门}&quot;">​</a></h2><p>现在完成时需要 have/has；I already packed 在本课目标结构中应补 have。</p><p><strong>对照例句：</strong> I have already packed my suitcase.</p><p>I have packed 构成现在完成时，already 常放在助动词与分词之间；当前结果是行李已收拾好。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-083">回看讲解和练习</a></p><h2 id="l84-·-现在完成时入门" tabindex="-1">L84 · 现在完成时入门 <a class="header-anchor" href="#l84-·-现在完成时入门" aria-label="Permalink to &quot;L84 · 现在完成时入门 {#l84-·-现在完成时入门}&quot;">​</a></h2><p>现在完成时需要 have/has；I already packed 在本课目标结构中应补 have。</p><p><strong>对照例句：</strong> Have you checked the train times yet?</p><p>Have 前置，checked 为过去分词；yet 位于句末，询问截至现在是否已完成核查。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-084">回看讲解和练习</a></p><h2 id="l85-·-have-been-to-与过去时间" tabindex="-1">L85 · have been to 与过去时间 <a class="header-anchor" href="#l85-·-have-been-to-与过去时间" aria-label="Permalink to &quot;L85 · have been to 与过去时间 {#l85-·-have-been-to-与过去时间}&quot;">​</a></h2><p>谈仍未回来的人用 has gone；不要把 gone 和 been 都译为无差别的“去过”。</p><p><strong>对照例句：</strong> I have been to Vienna twice.</p><p>Have been to 表过去去过且已经返回；twice 说明经历次数，不给出具体已结束的日期。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-085">回看讲解和练习</a></p><h2 id="l86-·-have-been-to-与过去时间" tabindex="-1">L86 · have been to 与过去时间 <a class="header-anchor" href="#l86-·-have-been-to-与过去时间" aria-label="Permalink to &quot;L86 · have been to 与过去时间 {#l86-·-have-been-to-与过去时间}&quot;">​</a></h2><p>谈仍未回来的人用 has gone；不要把 gone 和 been 都译为无差别的“去过”。</p><p><strong>对照例句：</strong> Rita has gone to the bank and will be back soon.</p><p>Has gone to 表丽塔已经离开去银行；will be back soon 提示她尚未回来，soon 是未来时间提示。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-086">回看讲解和练习</a></p><h2 id="l87-·-现在完成时的疑问与否定" tabindex="-1">L87 · 现在完成时的疑问与否定 <a class="header-anchor" href="#l87-·-现在完成时的疑问与否定" aria-label="Permalink to &quot;L87 · 现在完成时的疑问与否定 {#l87-·-现在完成时的疑问与否定}&quot;">​</a></h2><p>yet 在这里常位于句末；has 后不能直接跟 repair 原形。</p><p><strong>对照例句：</strong> The mechanic has not repaired my bicycle yet.</p><p>Has not repaired 为现在完成时否定；yet 放句末，表示截至目前仍未完成。my bicycle 为修理对象。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-087">回看讲解和练习</a></p><h2 id="l88-·-现在完成时的疑问与否定" tabindex="-1">L88 · 现在完成时的疑问与否定 <a class="header-anchor" href="#l88-·-现在完成时的疑问与否定" aria-label="Permalink to &quot;L88 · 现在完成时的疑问与否定 {#l88-·-现在完成时的疑问与否定}&quot;">​</a></h2><p>yet 在这里常位于句末；has 后不能直接跟 repair 原形。</p><p><strong>对照例句：</strong> Have they replaced the broken window yet?</p><p>Have they replaced 询问完成结果；broken 是修饰 window 的过去分词形容词，yet 询问是否已经。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-088">回看讲解和练习</a></p><h2 id="l89-·-since-与-for" tabindex="-1">L89 · since 与 for <a class="header-anchor" href="#l89-·-since-与-for" aria-label="Permalink to &quot;L89 · since 与 for {#l89-·-since-与-for}&quot;">​</a></h2><p>since 后不是 six years 这种时长；for six years 与 since 2020 不要混淆。</p><p><strong>对照例句：</strong> We have lived here for six years.</p><p>Have lived 表从过去持续到现在的居住；for six years 给出持续时长，不是起始日期。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-089">回看讲解和练习</a></p><h2 id="l90-·-since-与-for" tabindex="-1">L90 · since 与 for <a class="header-anchor" href="#l90-·-since-与-for" aria-label="Permalink to &quot;L90 · since 与 for {#l90-·-since-与-for}&quot;">​</a></h2><p>since 后不是 six years 这种时长；for six years 与 since 2020 不要混淆。</p><p><strong>对照例句：</strong> She has owned this flat since 2020.</p><p>Has owned 表持续的拥有状态；since 2020 给出起点，与延续到现在的状态配合。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-090">回看讲解和练习</a></p><h2 id="l91-·-will-表将来" tabindex="-1">L91 · will 表将来 <a class="header-anchor" href="#l91-·-will-表将来" aria-label="Permalink to &quot;L91 · will 表将来 {#l91-·-will-表将来}&quot;">​</a></h2><p>will 后接原形；will ready 缺少 be，不能直接跟形容词。</p><p><strong>对照例句：</strong> Our neighbours will move next month.</p><p>Our neighbours 为复数主语，但 will 对所有人称同形；move 用原形，next month 是将来时间。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-091">回看讲解和练习</a></p><h2 id="l92-·-will-表将来" tabindex="-1">L92 · will 表将来 <a class="header-anchor" href="#l92-·-will-表将来" aria-label="Permalink to &quot;L92 · will 表将来 {#l92-·-will-表将来}&quot;">​</a></h2><p>will 后接原形；will ready 缺少 be，不能直接跟形容词。</p><p><strong>对照例句：</strong> Will the new room be ready tomorrow?</p><p>Will 提前构成问句，the new room 为主语，be ready 构成系表结构；be 不能遗漏。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-092">回看讲解和练习</a></p><h2 id="l93-·-过去、现在与将来的时间线" tabindex="-1">L93 · 过去、现在与将来的时间线 <a class="header-anchor" href="#l93-·-过去、现在与将来的时间线" aria-label="Permalink to &quot;L93 · 过去、现在与将来的时间线 {#l93-·-过去、现在与将来的时间线}&quot;">​</a></h2><p>did 和 will 后都接原形，但表达的时间不同；不能把 Did he go tomorrow? 当正常将来问句。</p><p><strong>对照例句：</strong> Our neighbour flew to Madrid last week.</p><p>Flew 是 fly 的过去式，last week 指明确过去；to Madrid 表飞行目的地。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-093">回看讲解和练习</a></p><h2 id="l94-·-过去、现在与将来的时间线" tabindex="-1">L94 · 过去、现在与将来的时间线 <a class="header-anchor" href="#l94-·-过去、现在与将来的时间线" aria-label="Permalink to &quot;L94 · 过去、现在与将来的时间线 {#l94-·-过去、现在与将来的时间线}&quot;">​</a></h2><p>did 和 will 后都接原形，但表达的时间不同；不能把 Did he go tomorrow? 当正常将来问句。</p><p><strong>对照例句：</strong> He will return next Tuesday.</p><p>Will return 为将来结构，return 用原形；next Tuesday 前不用 on。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-094">回看讲解和练习</a></p><h2 id="l95-·-had-better-与时间表达" tabindex="-1">L95 · had better 与时间表达 <a class="header-anchor" href="#l95-·-had-better-与时间表达" aria-label="Permalink to &quot;L95 · had better 与时间表达 {#l95-·-had-better-与时间表达}&quot;">​</a></h2><p>had better 后不加 to；否定 not 放在 better 后，而不是用 don&#39;t。</p><p><strong>对照例句：</strong> We had better leave before the traffic gets heavy.</p><p>Had better 后直接接 leave，表示当前建议；before the traffic gets heavy 是时间从句，用现在时表达将来。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-095">回看讲解和练习</a></p><h2 id="l96-·-had-better-与时间表达" tabindex="-1">L96 · had better 与时间表达 <a class="header-anchor" href="#l96-·-had-better-与时间表达" aria-label="Permalink to &quot;L96 · had better 与时间表达 {#l96-·-had-better-与时间表达}&quot;">​</a></h2><p>had better 后不加 to；否定 not 放在 better 后，而不是用 don&#39;t。</p><p><strong>对照例句：</strong> You had better not miss the last train.</p><p>Had better not 加 miss 表否定建议；the last train 为宾语，had better 不是过去发生的动作。</p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-096">回看讲解和练习</a></p><h2 id="l97-·-名词性物主代词" tabindex="-1">L97 · 名词性物主代词 <a class="header-anchor" href="#l97-·-名词性物主代词" aria-label="Permalink to &quot;L97 · 名词性物主代词 {#l97-·-名词性物主代词}&quot;">​</a></h2><p>不能写 mine suitcase；名词前用 my，独立使用才用 mine。</p><p><strong>对照例句：</strong> The small green suitcase is mine.</p><p>The small green suitcase 是主语，small 表尺寸、green 表颜色；mine 独立作表语，后不再接 suitcase。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-097">回看讲解和练习</a></p><h2 id="l98-·-名词性物主代词" tabindex="-1">L98 · 名词性物主代词 <a class="header-anchor" href="#l98-·-名词性物主代词" aria-label="Permalink to &quot;L98 · 名词性物主代词 {#l98-·-名词性物主代词}&quot;">​</a></h2><p>不能写 mine suitcase；名词前用 my，独立使用才用 mine。</p><p><strong>对照例句：</strong> Are these keys yours or hers?</p><p>These keys 为复数主语，are 前置；yours 与 hers 都独立代表“某人的钥匙”，两者之间用 or 提供选择。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-098">回看讲解和练习</a></p><h2 id="l99-·-现在时引述与宾语从句" tabindex="-1">L99 · 现在时引述与宾语从句 <a class="header-anchor" href="#l99-·-现在时引述与宾语从句" aria-label="Permalink to &quot;L99 · 现在时引述与宾语从句 {#l99-·-现在时引述与宾语从句}&quot;">​</a></h2><p>say me 应改为 tell me 或 say to me；不要把 say 与 tell 的宾语结构混用。</p><p><strong>对照例句：</strong> Ben says that his ankle hurts.</p><p>Ben says 是主句，that his ankle hurts 是宾语从句；ankle 单数，所以从句谓语 hurt 加 s。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-099">回看讲解和练习</a></p><h2 id="l100-·-现在时引述与宾语从句" tabindex="-1">L100 · 现在时引述与宾语从句 <a class="header-anchor" href="#l100-·-现在时引述与宾语从句" aria-label="Permalink to &quot;L100 · 现在时引述与宾语从句 {#l100-·-现在时引述与宾语从句}&quot;">​</a></h2><p>say me 应改为 tell me 或 say to me；不要把 say 与 tell 的宾语结构混用。</p><p><strong>对照例句：</strong> She tells me that the floor is wet.</p><p>Tells 后接 me 表听话人，再接 that 从句；the floor is wet 使用完整陈述语序。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-100">回看讲解和练习</a></p><h2 id="l101-·-间接引语中的人称转换" tabindex="-1">L101 · 间接引语中的人称转换 <a class="header-anchor" href="#l101-·-间接引语中的人称转换" aria-label="Permalink to &quot;L101 · 间接引语中的人称转换 {#l101-·-间接引语中的人称转换}&quot;">​</a></h2><p>转述 Rita 的 my aunt 通常要变 her aunt，而不是保留成转述者的 my。</p><p><strong>对照例句：</strong> Rita says she is staying with her aunt.</p><p>Rita says 是现在时引述；she 与 her 都指 Rita，is staying 描述她现阶段的居住安排。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-101">回看讲解和练习</a></p><h2 id="l102-·-间接引语中的人称转换" tabindex="-1">L102 · 间接引语中的人称转换 <a class="header-anchor" href="#l102-·-间接引语中的人称转换" aria-label="Permalink to &quot;L102 · 间接引语中的人称转换 {#l102-·-间接引语中的人称转换}&quot;">​</a></h2><p>转述 Rita 的 my aunt 通常要变 her aunt，而不是保留成转述者的 my。</p><p><strong>对照例句：</strong> The boys say they will arrive tomorrow.</p><p>The boys say 是复数主语和原形谓语；从句 they will arrive 表将来，tomorrow 按当前转述时间理解。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-102">回看讲解和练习</a></p><h2 id="l103-·-too-very-enough" tabindex="-1">L103 · too/very/enough <a class="header-anchor" href="#l103-·-too-very-enough" aria-label="Permalink to &quot;L103 · too/very/enough {#l103-·-too-very-enough}&quot;">​</a></h2><p>形容词后用 enough；不要写 enough clear。too heavy 表示超出能承受范围，不只是“很重”。</p><p><strong>对照例句：</strong> The instructions are clear enough to follow.</p><p>Clear 是表语，enough 放在形容词之后；to follow 说明足够清楚所能完成的活动。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-103">回看讲解和练习</a></p><h2 id="l104-·-too-very-enough" tabindex="-1">L104 · too/very/enough <a class="header-anchor" href="#l104-·-too-very-enough" aria-label="Permalink to &quot;L104 · too/very/enough {#l104-·-too-very-enough}&quot;">​</a></h2><p>形容词后用 enough；不要写 enough clear。too heavy 表示超出能承受范围，不只是“很重”。</p><p><strong>对照例句：</strong> This suitcase is too heavy for me to lift.</p><p>Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-104">回看讲解和练习</a></p><h2 id="l105-·-动词-宾语-to-do" tabindex="-1">L105 · 动词 + 宾语 + to do <a class="header-anchor" href="#l105-·-动词-宾语-to-do" aria-label="Permalink to &quot;L105 · 动词 + 宾语 + to do {#l105-·-动词-宾语-to-do}&quot;">​</a></h2><p>tell her not to send 与 tell her to not send 相比，本课采用常见的 not to；不要用 tell she。</p><p><strong>对照例句：</strong> Please ask Leo to check the figures.</p><p>Ask 为祈使句谓语，Leo 为宾语，to check 为宾语补足语；实际执行 check 的人是 Leo。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-105">回看讲解和练习</a></p>',133)])])}const u=a(l,[["render",r]]);export{g as __pageData,u as default};
